insert into public.objectives (code, year_group, strand, title, child_title, rule) values ('Y3-V-prefixes', 3, 'vocabulary', 'Prefixes such as super-, anti-, auto-, dis-, mis-, re-, sub- and inter-', 'Prefixes', 'A prefix goes at the start of a word and changes its meaning: re- means again, dis- and mis- often mean not or wrongly.') on conflict (code) do update set year_group = excluded.year_group, strand = excluded.strand, title = excluded.title, child_title = excluded.child_title, rule = excluded.rule;
